80	export function camParamsAt(course: Course, s: number, blend = 8): CamParams {
81	  const acc: CamParams = { back: 0, up: 0, ahead: 0, lookUp: 0, fov: 0, latFollow: 0, roll: 0 };
82	  let w = 0;
83	  for (const st of course.stages) {
84	    const p = STAGE_CAM[st.id];
85	    if (!p) continue;
86	    const a = THREE.MathUtils.smoothstep(s, st.s0 - blend, st.s0 + blend) * (1 - THREE.MathUtils.smoothstep(s, st.s1 - blend, st.s1 + blend));
87	    if (a <= 0) continue;
88	    for (const k of KEYS) acc[k] += p[k] * a;
89	    w += a;
90	  }
91	  if (w === 0) return { ...(STAGE_CAM['03'] as CamParams) };
92	  for (const k of KEYS) acc[k] /= w;
93	  return acc;
94	}
