96	export class RideCamera {
97	  readonly pos = new THREE.Vector3();
98	  readonly target = new THREE.Vector3();
99	  readonly up = new THREE.Vector3(0, 1, 0);
100	  fov = 70;
101	  private init = false;
102	  /** optional straight tunnel axis + the s-range where the camera aligns to it */
103	  axis: { path: TubePath; s0: number; s1: number } | null = null;
104	  /** `?match06=1`: off06 / dir06 in the river's level frame at the 06 checkpoint (computed once) */
105	  private m06: { s0: number; o: number[]; d: number[] } | null = null;
106	  /** r21 m06view: approved vertical angle between Benny and the river 6 u ahead (rad) */
107	  private m06vSep: number | null = null;
108	
109	  constructor(private course: Course) {}
110	
111	  /** desired pose for Benny at (s, lateral) */
112	  desired(s: number, lat: number, outPos: THREE.Vector3, outTarget: THREE.Vector3, outUp: THREE.Vector3): CamParams {
113	    const p = camParamsAt(this.course, s);
114	    const f = this.course.sample(s);
115	    const fb = this.course.sample(Math.max(0, s - p.back * 0.5)); // smoothing of heading
116	    const dir = f.tan.clone().lerp(fb.tan, 0.35).normalize();
117	    let up = f.up.clone();
118	    if (this.axis) {
119	      const a = this.axis;
120	      const w = THREE.MathUtils.smoothstep(s, a.s0, a.s0 + 10) * (1 - THREE.MathUtils.smoothstep(s, a.s1 - 10, a.s1));
121	      if (w > 0) {
122	        const af = a.path.frame(s);
123	        dir.lerp(af.tan, w).normalize();
124	        up.lerp(af.up, w).normalize();
125	      }
126	    }
127	    up.addScaledVector(dir, -up.dot(dir)).normalize();
128	    const right = new THREE.Vector3().crossVectors(dir, up).normalize();
129	    const benny = f.pos.clone().addScaledVector(f.right, lat);
130	    const anchor = benny.clone().addScaledVector(right, -lat * (1 - p.latFollow));
131	    // offsets use an 'upright' up: banking only tilts the camera as much as `roll` allows
132	    const upPos = new THREE.Vector3(0, 1, 0).lerp(up, Math.max(p.roll, Math.abs(dir.y))).normalize();
133	    // position: ON the curved course behind Benny (stays inside bending/pitching tubes, e.g. the
134	    // 07 pull-up arc); aim: along his heading so he stays centred in winding streams
135	    const fbk = this.course.sample(Math.max(0, s - p.back));
136	    const upB = new THREE.Vector3(0, 1, 0).lerp(fbk.up, Math.max(p.roll, Math.abs(fbk.tan.y))).normalize();
137	    const straightPos = anchor.clone().addScaledVector(dir, -p.back).addScaledVector(upPos, p.up);
138	    const curvedPos = fbk.pos.clone().addScaledVector(fbk.right, lat * p.latFollow).addScaledVector(upB, p.up);
139	    // use the curved position where the path bends in pitch (plunge arcs), straight elsewhere
140	    const pitchBend = THREE.MathUtils.clamp(Math.abs(fbk.tan.y - f.tan.y) * 6, 0, 1);
141	    outPos.copy(straightPos).lerp(curvedPos, Math.max(pitchBend, 0.35));
142	    outTarget.copy(anchor).addScaledVector(dir, p.ahead).addScaledVector(upPos, p.lookUp);
143	    outUp.set(0, 1, 0).lerp(up, p.roll).normalize();
144	    // `?match07=1`: approved-picture framing in 07 — yaw the view and shift the camera sideways (both 0 / absent by default)
145	    const p7 = STAGE_CAM['07'];
146	    if (p7 && (p7.yaw07 || p7.side07)) {
147	      const st7 = this.course.stage('07');
148	      const sTop = this.course.marks['07_plunge_top'];
149	      const w7 = THREE.MathUtils.smoothstep(s, st7.s0 + 2, st7.s0 + 10) * (1 - THREE.MathUtils.smoothstep(s, sTop - 12, sTop - 2));
150	      if (w7 > 0) {
151	        const fwd = outTarget.clone().sub(outPos);
152	        fwd.applyAxisAngle(outUp, THREE.MathUtils.degToRad((p7.yaw07 ?? 0) * w7));
153	        const side = new THREE.Vector3().crossVectors(fwd, outUp).normalize().multiplyScalar((p7.side07 ?? 0) * w7);
154	        outPos.add(side);
155	        outTarget.copy(outPos).add(fwd);
156	      }
157	    }
158	    // `?match08=1`: the approved Screen 08 view — camera at Benny + off08 (world), aimed at aim08 near the chamber door,
159	    // level (no bank roll); blended in just before the 08 checkpoint and out before 09 (absent = no change)
160	    const p8 = STAGE_CAM['08'];
161	    if (p8 && p8.off08 && p8.aim08) {
162	      const st8 = this.course.stage('08');
163	      const w8 = THREE.MathUtils.smoothstep(s, st8.s0 - 3, st8.s0 + 1.5) * (1 - THREE.MathUtils.smoothstep(s, st8.s1 - 10, st8.s1 - 1));
164	      if (w8 > 0) {
165	        outPos.lerp(benny.clone().add(new THREE.Vector3(...p8.off08)), w8);
166	        outTarget.lerp(new THREE.Vector3(...p8.aim08), w8);
167	        outUp.lerp(new THREE.Vector3(0, 1, 0), w8).normalize();
